def auc(pairs):
    pos = [s for s, y in pairs if y]; neg = [s for s, y in pairs if not y]
    win = sum((p > n) + 0.5 * (p == n) for p in pos for n in neg)
    return win / (len(pos) * len(neg))
data = {"생수": [(0.9, 0), (0.8, 1), (0.85, 1), (0.7, 0), (0.75, 1)],
        "캠핑의자": [(0.3, 1), (0.1, 0), (0.35, 0), (0.2, 0), (0.25, 0)]}
allp = [x for v in data.values() for x in v]
print("전체 AUC", round(auc(allp), 3))
g = {q: round(auc(v), 3) for q, v in data.items()}
print("검색어별 AUC", g, "평균(GAUC)", round(sum(g.values()) / len(g), 3))
# 전체 AUC 0.75
# 검색어별 AUC {'생수': 0.5, '캠핑의자': 0.75} 평균(GAUC) 0.625

import random
random.seed(7)
true = {"상품1": 0.04, "상품2": 0.06, "신상품": 0.09}
ab = {k: [1, 1] for k in true}
shown = {k: 0 for k in true}
for t in range(5000):
    pick = max(ab, key=lambda k: random.betavariate(*ab[k]))
    shown[pick] += 1
    if random.random() < true[pick]: ab[pick][0] += 1
    else: ab[pick][1] += 1
print(shown)
# {'상품1': 168, '상품2': 271, '신상품': 4561}

import math
def wilson_lb(c, n, z=1.96):
    p = c / n
    return (p + z*z/(2*n) - z*math.sqrt(p*(1-p)/n + z*z/(4*n*n))) / (1 + z*z/n)
for name, c, n in [("신상품 A", 1, 2), ("스테디 B", 40, 1000)]:
    print(name, "CTR", round(c/n, 3), "하한", round(wilson_lb(c, n), 3))
# 신상품 A CTR 0.5 하한 0.095
# 스테디 B CTR 0.04 하한 0.03
